            if unit=='USD_millions':facts.append(fact(a+'→'+b,m,(y-x)/x*100 if x and x>0 else None,'(new - old) / old * 100',ops,'percent',':percent_change'))
        comparisons[a+'→'+b]={'complete':True,'missing_months':[],'facts':facts}
